html{color-scheme:var(--dodai-scheme)}
body{margin:0;background:var(--dodai-background);color:var(--dodai-text);font-family:var(--dodai-font-body);font-size:var(--dodai-size-md);line-height:1.5}
h1,h2,h3,h4,.dodai-heading{font-family:var(--dodai-font-display);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);margin:0 0 var(--dodai-space-sm);color:var(--dodai-text)}
h1{font-size:var(--dodai-size-xxl);color:var(--dodai-primary)}
h2{font-size:var(--dodai-size-xl)}
h3{font-size:var(--dodai-size-lg)}
h4{font-size:var(--dodai-size-md)}
.dodai-label{display:inline-block;font-family:var(--dodai-font-display);font-size:var(--dodai-size-sm);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);color:var(--dodai-text-muted)}
a{color:var(--dodai-link);text-decoration:none}
a:hover{color:var(--dodai-secondary-hover);text-decoration:underline}
code,pre,.dodai-mono{font-family:var(--dodai-font-mono)}
::selection{background:var(--dodai-selection)}
:focus-visible{outline:var(--dodai-border-width) solid var(--dodai-focus-ring);outline-offset:2px}
.dodai-muted{color:var(--dodai-text-muted)}
.dodai-chamfer{clip-path:var(--dodai-clip)}

/* Framed surfaces (button, panel): ::before = chamfer border ring, ::after = fill.
   The element itself is never clipped so glow (box-shadow or drop-shadow) stays visible. */
.dodai-btn,.dodai-panel{position:relative;isolation:isolate;border-radius:var(--dodai-radius);
  box-shadow:inset 0 0 0 var(--dodai-ring-inset) var(--f-bd),var(--f-glow,0 0 0 0 transparent);filter:var(--f-filter,none)}
.dodai-btn::before,.dodai-panel::before,.dodai-btn::after,.dodai-panel::after{content:"";position:absolute;z-index:-1;pointer-events:none}
.dodai-btn::before,.dodai-panel::before{inset:0;background:var(--f-bd);clip-path:var(--dodai-clip-ring)}
.dodai-btn::after,.dodai-panel::after{inset:var(--dodai-border-width);background:var(--f-bg);border-radius:var(--dodai-inner-radius);clip-path:var(--dodai-clip-inner);transition:background .12s}

/* Busy shimmer: a band sweeps over the fill, inside its outline (brightening to its right edge);
   a light sweep on filled buttons, the accent itself on outline and ghost ones. */
.dodai-btn--shimmer{--f-sheen:var(--dodai-highlight)}
.dodai-btn--shimmer.dodai-btn--outline,.dodai-btn--shimmer.dodai-btn--outline-secondary,.dodai-btn--shimmer.dodai-btn--ghost{--f-sheen:color-mix(in srgb,var(--b-fg) 25%,transparent)}
.dodai-btn--shimmer::after{background:linear-gradient(90deg,transparent,var(--f-sheen)) no-repeat,var(--f-bg);
  background-size:40% 100%,auto;animation:dodai-sweep 1.4s linear infinite}
@keyframes dodai-sweep{from{background-position:-66.667% 0,0 0}to{background-position:166.667% 0,0 0}}

/* Double tick a cut-corner crop draws on the far end of a button */
.dodai-tick{position:absolute;top:50%;width:var(--dodai-space-md);box-sizing:content-box;
  height:var(--dodai-tick-gap);transform:translateY(-50%);pointer-events:none;
  border-top:var(--dodai-border-width) solid var(--b-fg);border-bottom:var(--dodai-border-width) solid var(--b-fg)}
.dodai-tick--left{left:0}.dodai-tick--right{right:0}

/* Buttons */
.dodai-btn{--f-bg:var(--dodai-primary);--f-bd:var(--dodai-primary);--b-fg:var(--dodai-on-primary);
  display:inline-flex;align-items:center;justify-content:center;gap:var(--dodai-space-sm);
  min-height:var(--dodai-control-height);padding:0 var(--dodai-space-lg);border:0;cursor:pointer;background:transparent;
  color:var(--b-fg);font:inherit;font-family:var(--dodai-font-display);
  text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);text-decoration:none;user-select:none;
  transition:color .12s,filter .12s,box-shadow .12s}
.dodai-btn:hover{--f-glow:var(--dodai-glow-shadow);--f-filter:var(--dodai-glow-filter);text-decoration:none}
.dodai-btn--primary:hover{--f-bg:var(--dodai-primary-hover);--f-bd:var(--dodai-primary-hover)}
.dodai-btn--primary:active{--f-bg:var(--dodai-primary-active);--f-bd:var(--dodai-primary-active)}
.dodai-btn--secondary{--f-bg:var(--dodai-secondary);--f-bd:var(--dodai-secondary);--b-fg:var(--dodai-on-secondary)}
.dodai-btn--secondary:hover{--f-bg:var(--dodai-secondary-hover);--f-bd:var(--dodai-secondary-hover);--b-fg:var(--dodai-on-secondary-hover)}
.dodai-btn--secondary:active{--f-bg:var(--dodai-secondary-active);--f-bd:var(--dodai-secondary-active)}
.dodai-btn--danger{--f-bg:var(--dodai-danger);--f-bd:var(--dodai-danger);--b-fg:var(--dodai-on-danger)}
.dodai-btn--danger:hover{--f-bg:var(--dodai-danger-hover);--f-bd:var(--dodai-danger-hover)}
.dodai-btn--danger:active{--f-bg:var(--dodai-danger-active);--f-bd:var(--dodai-danger-active)}
.dodai-btn--outline,.dodai-btn--outline-secondary{--c:var(--dodai-primary);--oc:var(--dodai-on-primary-solid);--f-bg:transparent;--f-bd:var(--c);--b-fg:var(--c)}
.dodai-btn--outline-secondary{--c:var(--dodai-secondary);--oc:var(--dodai-on-secondary-solid)}
.dodai-btn--scrim{--c:var(--dodai-primary);--oc:var(--dodai-on-primary-solid);--f-bg:color-mix(in srgb,var(--dodai-background) 50%,transparent);--f-bd:var(--c);--b-fg:var(--c)}
.dodai-btn--outline:hover,.dodai-btn--outline-secondary:hover,.dodai-btn--scrim:hover{--f-bg:var(--c);--b-fg:var(--oc)}
.dodai-btn--ghost{--f-bg:transparent;--f-bd:transparent;--b-fg:var(--dodai-text)}
.dodai-btn--ghost:hover{--f-bg:var(--dodai-surface-raised);--b-fg:var(--dodai-primary);--f-glow:0 0 0 0 transparent;--f-filter:none}
.dodai-btn:disabled,.dodai-btn[aria-disabled=true]{--f-bg:var(--dodai-surface-raised);--f-bd:var(--dodai-surface-raised);--b-fg:var(--dodai-text-disabled);cursor:not-allowed;--f-glow:0 0 0 0 transparent;--f-filter:none}

/* Panels / cards */
.dodai-panel{--f-bg:var(--dodai-surface);--f-bd:var(--dodai-panel-bd);padding:var(--dodai-space-md);color:var(--dodai-text);
  box-shadow:inset 0 0 0 var(--dodai-panel-ring) var(--f-bd),var(--f-glow,0 0 0 0 transparent)}
.dodai-panel::after{inset:var(--dodai-panel-bw)}
.dodai-panel__shade{position:absolute;inset:0;z-index:-2;translate:var(--dodai-panel-sx) var(--dodai-panel-sy);background:var(--dodai-panel-sc);
  clip-path:var(--dodai-clip);border-radius:var(--dodai-radius);pointer-events:none}
.dodai-panel--focus{--f-bd:var(--dodai-primary);--f-glow:var(--dodai-glow-shadow);--f-filter:var(--dodai-glow-filter)}
.dodai-panel--raised{--f-bg:var(--dodai-surface-raised)}
.dodai-panel__title{font-family:var(--dodai-font-display);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);color:var(--dodai-text-muted);font-size:var(--dodai-size-sm);margin-bottom:var(--dodai-space-sm)}
.dodai-panel--focus .dodai-panel__title{color:var(--dodai-primary)}

/* Inputs */
.dodai-input,.dodai-textarea,.dodai-select{display:block;width:100%;min-height:var(--dodai-control-height);padding:0 var(--dodai-space-md);background:var(--dodai-background);color:var(--dodai-text);
  border:var(--dodai-border-width) solid var(--dodai-border-strong);border-radius:var(--dodai-radius);font:inherit;transition:border-color .12s,box-shadow .12s}
.dodai-textarea{padding:var(--dodai-space-sm) var(--dodai-space-md);min-height:calc(var(--dodai-control-height) * 2);resize:vertical}
.dodai-select{appearance:none;-webkit-appearance:none;padding-right:calc(var(--dodai-space-md) * 2 + 10px);cursor:pointer;
  background-image:linear-gradient(45deg,transparent 50%,var(--dodai-text-muted) 50%),linear-gradient(135deg,var(--dodai-text-muted) 50%,transparent 50%);
  background-position:calc(100% - var(--dodai-space-md) - 5px) 50%,calc(100% - var(--dodai-space-md)) 50%;background-size:5px 5px;background-repeat:no-repeat}
.dodai-input::placeholder,.dodai-textarea::placeholder{color:var(--dodai-text-disabled)}
.dodai-input:focus,.dodai-textarea:focus,.dodai-select:focus{outline:none;border-color:var(--dodai-secondary);box-shadow:0 0 var(--dodai-glow-blur) var(--dodai-secondary)}
.dodai-input:disabled,.dodai-textarea:disabled,.dodai-select:disabled{color:var(--dodai-text-disabled);background:var(--dodai-surface-raised);border-color:var(--dodai-border);cursor:not-allowed}
.dodai-input::selection,.dodai-textarea::selection{background:var(--dodai-selection)}
.dodai-field{display:grid;gap:var(--dodai-space-xs)}

/* Tags / badges */
.dodai-tag,.dodai-badge{--t:var(--dodai-info);--tf:var(--dodai-on-info-solid);--ts:var(--dodai-info-soft);display:inline-block;padding:2px var(--dodai-space-sm);font-size:var(--dodai-size-xs);line-height:1.5;
  font-family:var(--dodai-font-display);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);background:var(--t);color:var(--tf);border-radius:var(--dodai-radius);clip-path:var(--dodai-clip-sm);white-space:nowrap}
.dodai-tag--success{--t:var(--dodai-success);--tf:var(--dodai-on-success-solid);--ts:var(--dodai-success-soft)}
.dodai-tag--warning{--t:var(--dodai-warning);--tf:var(--dodai-on-warning-solid);--ts:var(--dodai-warning-soft)}
.dodai-tag--danger{--t:var(--dodai-danger);--tf:var(--dodai-on-danger-solid);--ts:var(--dodai-danger-soft)}
.dodai-tag--primary{--t:var(--dodai-primary);--tf:var(--dodai-on-primary-solid);--ts:var(--dodai-primary-soft)}
.dodai-tag--secondary{--t:var(--dodai-secondary);--tf:var(--dodai-on-secondary-solid);--ts:var(--dodai-secondary-soft)}
.dodai-tag--soft{background:var(--ts);color:var(--t);box-shadow:inset 0 0 0 var(--dodai-border-width) var(--t)}
.dodai-badge{min-width:1.6em;padding:0 var(--dodai-space-xs);text-align:center;border-radius:var(--dodai-radius)}

/* Tabs */
.dodai-tabs{display:flex;gap:var(--dodai-space-xs);border-bottom:var(--dodai-border-width) solid var(--dodai-border)}
.dodai-tab{padding:var(--dodai-space-sm) var(--dodai-space-md);color:var(--dodai-text-muted);font-family:var(--dodai-font-display);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);text-decoration:none;
  border-bottom:var(--dodai-border-width) solid transparent;margin-bottom:calc(var(--dodai-border-width) * -1);border-radius:var(--dodai-radius) var(--dodai-radius) 0 0;clip-path:var(--dodai-clip-sm);transition:background .12s,color .12s}
.dodai-tab:hover{background:var(--dodai-surface-raised);color:var(--dodai-text);text-decoration:none}
.dodai-tab--active,.dodai-tab[aria-current=page],.dodai-tab--active:hover{background:var(--dodai-primary);color:var(--dodai-on-primary);border-bottom-color:var(--dodai-primary)}
.dodai-tabs--secondary .dodai-tab--active,.dodai-tabs--secondary .dodai-tab--active:hover{background:none;color:var(--dodai-primary);box-shadow:inset 0 -2px var(--dodai-primary)}
.dodai-tab--disabled{opacity:.45;pointer-events:none}
.dodai-tab--icon{display:inline-flex;flex-direction:column;align-items:center;gap:var(--dodai-space-xs)}

/* Tables */
.dodai-table{width:100%;border-collapse:collapse}
.dodai-table th{font-family:var(--dodai-font-display);text-transform:var(--dodai-label-case);letter-spacing:var(--dodai-tracking);color:var(--dodai-primary);text-align:left;font-size:var(--dodai-size-sm);border-bottom:var(--dodai-border-width) solid var(--dodai-primary)}
.dodai-table th,.dodai-table td{padding:var(--dodai-space-sm) var(--dodai-space-md)}
.dodai-table tbody tr{border-bottom:1px solid var(--dodai-border)}
.dodai-table tbody tr:hover{background:var(--dodai-selection)}

/* Progress */
.dodai-progress{height:8px;background:var(--dodai-surface-raised);border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);overflow:hidden}
.dodai-progress>span{display:block;height:100%;width:var(--v,50%);background:var(--p,var(--dodai-primary));box-shadow:var(--dodai-glow-shadow)}
.dodai-progress--success{--p:var(--dodai-success)}.dodai-progress--warning{--p:var(--dodai-warning)}.dodai-progress--danger{--p:var(--dodai-danger)}

/* Switch / checkbox / radio: <label class="dodai-switch|dodai-check|dodai-radio"><input type=…><span class="…__box"></span>Label</label> */
.dodai-switch,.dodai-check,.dodai-radio{display:inline-flex;align-items:center;gap:var(--dodai-space-sm);cursor:pointer;position:relative;user-select:none}
.dodai-switch>input,.dodai-check>input,.dodai-radio>input{position:absolute;opacity:0;width:0;height:0;margin:0}
.dodai-switch__box{position:relative;width:40px;height:22px;flex:none;background:var(--dodai-surface-raised);border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);transition:background .12s,border-color .12s}
.dodai-switch__box::after{content:"";position:absolute;top:2px;left:2px;width:calc(22px - 4px - var(--dodai-border-width) * 2);height:calc(22px - 4px - var(--dodai-border-width) * 2);background:var(--dodai-text-muted);border-radius:var(--dodai-inner-radius);transition:transform .12s,background .12s}
.dodai-switch>input:checked+.dodai-switch__box{background:var(--dodai-primary);border-color:var(--dodai-primary);box-shadow:var(--dodai-glow-shadow)}
.dodai-switch>input:checked+.dodai-switch__box::after{background:var(--dodai-on-primary);transform:translateX(18px)}
.dodai-check__box,.dodai-radio__box{position:relative;width:18px;height:18px;flex:none;background:var(--dodai-surface-raised);border:var(--dodai-border-width) solid var(--dodai-border-strong);border-radius:var(--dodai-radius);transition:background .12s,border-color .12s}
.dodai-radio__box{border-radius:50%}
.dodai-check>input:checked+.dodai-check__box,.dodai-radio>input:checked+.dodai-radio__box{background:var(--dodai-primary);border-color:var(--dodai-primary)}
.dodai-check__box::after{content:"";position:absolute;left:5px;top:1px;width:5px;height:10px;border:solid var(--dodai-on-primary);border-width:0 2px 2px 0;transform:rotate(45deg) scale(0)}
.dodai-check>input:checked+.dodai-check__box::after{transform:rotate(45deg) scale(1)}
.dodai-check--mixed>.dodai-check__box{background:var(--dodai-primary);border-color:var(--dodai-primary)}
.dodai-check--mixed>.dodai-check__box::after,.dodai-check--mixed>input:checked+.dodai-check__box::after{left:3px;top:7px;width:10px;height:0;border-width:0 0 2px 0;transform:none}
.dodai-radio__box::after{content:"";position:absolute;inset:4px;border-radius:50%;background:var(--dodai-on-primary);transform:scale(0)}
.dodai-radio>input:checked+.dodai-radio__box::after{transform:scale(1)}
.dodai-switch:hover .dodai-switch__box,.dodai-check:hover .dodai-check__box,.dodai-radio:hover .dodai-radio__box{border-color:var(--dodai-primary-hover)}
.dodai-switch>input:focus-visible+*,.dodai-check>input:focus-visible+*,.dodai-radio>input:focus-visible+*{outline:var(--dodai-border-width) solid var(--dodai-focus-ring);outline-offset:2px}
.dodai-switch>input:disabled+*,.dodai-check>input:disabled+*,.dodai-radio>input:disabled+*{opacity:.45;cursor:not-allowed}

/* Slider */
.dodai-slider{--v:50%;appearance:none;-webkit-appearance:none;width:100%;height:20px;background:transparent;margin:0;cursor:pointer}
.dodai-slider::-webkit-slider-runnable-track{height:6px;border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);background:linear-gradient(var(--dir,to right),var(--dodai-surface-raised) var(--a,0%),var(--dodai-primary) var(--a,0%),var(--dodai-primary) var(--v),var(--dodai-surface-raised) var(--v))}
.dodai-slider::-moz-range-track{height:6px;border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);background:linear-gradient(var(--dir,to right),var(--dodai-surface-raised) var(--a,0%),var(--dodai-primary) var(--a,0%),var(--dodai-primary) var(--v),var(--dodai-surface-raised) var(--v))}
.dodai-slider-box{position:relative;width:100%}
.dodai-slider__tick{position:absolute;top:5px;width:2px;height:10px;margin-left:-1px;background:var(--dodai-border-strong);pointer-events:none}
.dodai-slider-box[style*="padding-top"]>.dodai-slider__tick{top:35px}
.dodai-slider__bubble{position:absolute;transform:translateX(-50%);height:22px;padding:0 var(--dodai-space-sm);display:flex;align-items:center;white-space:nowrap;font-size:var(--dodai-size-xs);color:var(--dodai-text);background:var(--dodai-surface-raised);border:1px solid var(--dodai-border);border-radius:var(--dodai-radius);pointer-events:none}
.dodai-slider::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;margin-top:-6px;background:var(--dodai-primary);border:var(--dodai-border-width) solid var(--dodai-on-primary);border-radius:var(--dodai-radius);box-shadow:var(--dodai-glow-shadow)}
.dodai-slider::-moz-range-thumb{width:14px;height:14px;background:var(--dodai-primary);border:var(--dodai-border-width) solid var(--dodai-on-primary);border-radius:var(--dodai-radius);box-shadow:var(--dodai-glow-shadow)}
.dodai-slider--v{--dir:to top;writing-mode:vertical-lr;direction:rtl;width:20px}
.dodai-slider--v::-webkit-slider-runnable-track{width:6px;height:100%}
.dodai-slider--v::-webkit-slider-thumb{margin-top:0;margin-left:-6px}
.dodai-knob{display:block}
.dodai-slider:disabled{opacity:.45;cursor:not-allowed}
/* Range: two sliders over one track filled between --a and --b; only the thumbs take the pointer */
.dodai-range{--a:0%;--b:100%;--dir:to right;position:relative;width:100%;height:20px}
.dodai-range::before{content:"";position:absolute;left:0;right:0;top:7px;height:6px;box-sizing:border-box;border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);background:linear-gradient(var(--dir),var(--dodai-surface-raised) var(--a),var(--dodai-primary) var(--a),var(--dodai-primary) var(--b),var(--dodai-surface-raised) var(--b))}
.dodai-range>.dodai-slider{position:absolute;inset:0;pointer-events:none}
.dodai-range>.dodai-slider::-webkit-slider-runnable-track{background:transparent;border-color:transparent}
.dodai-range>.dodai-slider::-moz-range-track{background:transparent;border-color:transparent}
.dodai-range>.dodai-slider::-webkit-slider-thumb{pointer-events:auto}
.dodai-range>.dodai-slider::-moz-range-thumb{pointer-events:auto}
.dodai-range--v{--dir:to top;width:20px}
.dodai-range--v::before{left:7px;right:auto;top:0;bottom:0;width:6px;height:auto}
.dodai-range--v>.dodai-slider{height:100%}

/* List */
.dodai-list{list-style:none;margin:0;padding:0;border:var(--dodai-border-width) solid var(--dodai-border);border-radius:var(--dodai-radius);background:var(--dodai-surface);overflow:hidden}
.dodai-list__item{padding:var(--dodai-space-sm) var(--dodai-space-md);color:var(--dodai-text-muted);border-left:3px solid transparent;cursor:pointer;transition:background .12s,color .12s}
.dodai-list__item:hover{background:var(--dodai-surface-raised);color:var(--dodai-text)}
.dodai-list__item[aria-selected=true],.dodai-list__item--selected{background:var(--dodai-selection);color:var(--dodai-text);border-left-color:var(--dodai-primary)}

/* Divider */
.dodai-divider{border:0;border-top:var(--dodai-border-width) solid var(--dodai-border);margin:var(--dodai-space-md) 0;height:0}

/* Tooltip: static bubble, or CSS-only on hover via data-tip */
.dodai-tooltip,.dodai-tip[data-tip]::after{display:inline-block;padding:var(--dodai-space-xs) var(--dodai-space-sm);background:var(--dodai-surface-raised);color:var(--dodai-text);border:var(--dodai-border-width) solid var(--dodai-border-strong);
  border-radius:var(--dodai-radius);clip-path:var(--dodai-clip-sm);font-size:var(--dodai-size-sm);box-shadow:var(--dodai-hard-x) var(--dodai-hard-y) 0 var(--dodai-border)}
.dodai-tip{position:relative;display:inline-block}
.dodai-tip[data-tip]::after{content:attr(data-tip);position:absolute;bottom:calc(100% + var(--dodai-space-sm));left:50%;transform:translateX(-50%);white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .12s;z-index:10}
.dodai-tip[data-tip]:hover::after,.dodai-tip[data-tip]:focus-within::after{opacity:1}

/* CRT scanlines (enabled per theme via --dodai-scanlines: 1) */
body::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:9999;opacity:var(--dodai-scanlines);
  background:repeating-linear-gradient(to bottom,transparent 0,transparent 2px,rgba(0,0,0,.28) 3px)}

/* Kit boxes: one generic box, pointed at a kit's variables by `kit_style()` (inline --kb, --kd, ...). */
.dodai-kit{background:var(--kb,transparent);color:var(--kf,inherit);border:var(--dodai-border-width) solid var(--kd,transparent);padding:var(--ky,0) var(--kx,0);
  border-radius:var(--kr,var(--dodai-radius));box-shadow:var(--kl,0 0 0 0 transparent),var(--kg,0 0 0 0 transparent);display:flex;align-items:center;gap:var(--dodai-space-sm);min-width:0}
.dodai-kit--press{cursor:pointer;user-select:none;font:inherit;text-align:left;transition:background .12s,border-color .12s,color .12s}
.dodai-kit--press:hover{background:var(--kbh,var(--kb));border-color:var(--kdh,var(--kd));color:var(--kfh,var(--kf))}
.dodai-kit--card{flex-direction:column;align-items:stretch;gap:var(--dodai-space-sm);min-width:180px}
.dodai-kit--popup{box-shadow:var(--dodai-hard-x) var(--dodai-hard-y) 0 var(--dodai-border-strong),0 8px 24px rgba(0,0,0,.18)}
.dodai-kit--block{display:flex}
.dodai-kit--col{flex-direction:column;align-items:stretch}

/* Layout helpers used by the showcase and the stack node */
.dodai-stack{display:flex;gap:var(--dodai-space-md);min-width:0}
.dodai-stack--row{flex-direction:row;align-items:center}
.dodai-stack--col{flex-direction:column;align-items:stretch}
.dodai-stack--wrap{flex-wrap:wrap}
.dodai-gap-xs{gap:var(--dodai-space-xs)}.dodai-gap-sm{gap:var(--dodai-space-sm)}.dodai-gap-md{gap:var(--dodai-space-md)}.dodai-gap-lg{gap:var(--dodai-space-lg)}
.dodai-caption{font-size:var(--dodai-size-xs);color:var(--dodai-text-muted)}
.dodai-sm{font-size:var(--dodai-size-sm)}

/* Buttons: sizes, square, icon-only, loading */
.dodai-btn--xs{min-height:calc(var(--dodai-control-height) * .75);padding:0 calc(var(--dodai-space-md) * .75);font-size:var(--dodai-size-sm)}
.dodai-btn--sm{min-height:var(--dodai-control-height);padding:0 var(--dodai-space-md);font-size:var(--dodai-size-md)}
.dodai-btn--md{min-height:calc(var(--dodai-control-height) * 1.25);padding:0 calc(var(--dodai-space-md) * 1.25);font-size:var(--dodai-size-lg)}
.dodai-btn--lg{min-height:calc(var(--dodai-control-height) * 1.6);padding:0 calc(var(--dodai-space-md) * 1.75);font-size:var(--dodai-size-xl)}
.dodai-btn--xl{min-height:calc(var(--dodai-control-height) * 2);padding:0 calc(var(--dodai-space-md) * 2.25);font-size:var(--dodai-size-xxl)}
.dodai-btn--icon{padding:0;aspect-ratio:1}
.dodai-btn--xs.dodai-btn--icon{width:calc(var(--dodai-control-height) * .75)}.dodai-btn--sm.dodai-btn--icon{width:var(--dodai-control-height)}
.dodai-btn--md.dodai-btn--icon{width:calc(var(--dodai-control-height) * 1.25)}.dodai-btn--lg.dodai-btn--icon{width:calc(var(--dodai-control-height) * 1.6)}.dodai-btn--xl.dodai-btn--icon{width:calc(var(--dodai-control-height) * 2)}
.dodai-btn--square{border-radius:var(--dodai-radius)}
.dodai-btn svg,.dodai-icon svg{display:block}
.dodai-split{display:inline-flex;gap:2px}

/* Busy indicators */
@keyframes dodai-spin{to{transform:rotate(360deg)}}
.dodai-spinner{display:inline-block;width:var(--s,24px);height:var(--s,24px);flex:none;border-radius:50%;border:max(2px,calc(var(--s,24px) / 8)) solid var(--dodai-border);border-top-color:var(--dodai-primary);animation:dodai-spin 1.1s linear infinite}
/* Other shapes: cells are positioned inline, each starts part-way through the same 1.11 s cycle. */
.dodai-spinner--bars,.dodai-spinner--orbit,.dodai-spinner--steps,.dodai-spinner--grid,.dodai-spinner--scanner,.dodai-spinner--hop,.dodai-spinner--petals{position:relative;border:0;border-radius:0;animation:none}
.dodai-spinner>i{position:absolute;background:var(--dodai-primary);animation:dodai-trail 1.111s linear infinite}
.dodai-spinner--bars>i{transform-origin:50% 100%;animation-name:dodai-trail-bar}
.dodai-spinner--orbit>i{border-radius:50%}
.dodai-spinner--steps>i{animation-name:dodai-trail-step}
.dodai-spinner--grid>i,.dodai-spinner--petals>i{animation-name:dodai-trail-grid}
.dodai-spinner--petals>i{border-radius:50%}
.dodai-spinner--scanner>i{animation-name:dodai-trail-scan}
.dodai-spinner--hop>i{animation-name:dodai-trail-hop}
@keyframes dodai-trail{from{opacity:1}to{opacity:.15}}
@keyframes dodai-trail-bar{from{opacity:1;transform:scaleY(1)}to{opacity:.15;transform:scaleY(.4)}}
@keyframes dodai-trail-grid{0%{opacity:1;transform:scale(1)}50%,100%{opacity:.15;transform:scale(.45)}}
@keyframes dodai-trail-scan{0%{opacity:1;transform:scaleY(1)}55%,88%{opacity:.15;transform:scaleY(.49)}100%{opacity:1;transform:scaleY(1)}}
@keyframes dodai-trail-hop{0%,40%,100%{opacity:.8;transform:translateY(0)}20%{opacity:1;transform:translateY(calc(var(--s) * -.52))}}
@keyframes dodai-trail-step{0%,24.9%{opacity:1}25%,100%{opacity:.15}}
@keyframes dodai-slide{from{left:-30%}to{left:100%}}
.dodai-indeterminate{position:relative;height:4px;overflow:hidden;border-radius:9999px;background:var(--dodai-surface-raised);width:100%;max-width:420px}
.dodai-indeterminate>span{position:absolute;top:0;bottom:0;width:30%;background:var(--dodai-primary);border-radius:9999px;animation:dodai-slide 1.4s linear infinite}
@keyframes dodai-shimmer{0%{opacity:.55}50%{opacity:1}100%{opacity:.55}}
.dodai-skeleton{display:block;height:16px;border-radius:var(--dodai-radius);background:var(--dodai-surface-raised);animation:dodai-shimmer 1.4s ease-in-out infinite}

/* Avatar, badge anchor, rating, stepper, breadcrumb, pagination */
.dodai-avatar{display:inline-grid;place-items:center;width:40px;height:40px;flex:none;font-size:var(--dodai-size-sm);font-family:var(--dodai-font-display)}
.dodai-badged{position:relative;display:inline-flex}
.dodai-badged>.dodai-kit{position:absolute;top:-2px;right:-2px;font-size:var(--dodai-size-xs);line-height:1.3}
.dodai-badged>.dodai-kit--dot{width:10px;height:10px;padding:0}
.dodai-rating{display:inline-flex;gap:2px}
.dodai-stepper{display:inline-flex;align-items:center;gap:var(--dodai-space-sm)}
.dodai-crumbs{display:flex;align-items:center;gap:var(--dodai-space-sm);color:var(--dodai-text-muted)}
.dodai-crumbs>:last-child{color:var(--dodai-text)}
.dodai-pager{display:inline-flex;align-items:center;gap:var(--dodai-space-xs)}
.dodai-pager .dodai-kit{min-width:34px;height:34px;justify-content:center}

/* Steps, timeline, tree, table, code, empty, swatch */
.dodai-steps{display:flex;align-items:center;gap:var(--dodai-space-sm);flex-wrap:wrap}
.dodai-steps__line{width:32px;height:1px;background:var(--dodai-border-strong)}
.dodai-step-dot{width:28px;height:28px;padding:0;justify-content:center;flex:none}
.dodai-timeline{display:grid;gap:var(--dodai-space-md)}
.dodai-timeline__item{display:flex;gap:var(--dodai-space-md);align-items:flex-start}
.dodai-timeline__item>.dodai-kit{width:12px;height:12px;padding:0;margin-top:5px;flex:none}
.dodai-tree{display:grid;max-width:420px}
.dodai-tree details>summary{list-style:none}
.dodai-tree details>summary::-webkit-details-marker{display:none}
.dodai-tree__children{padding-left:18px}
.dodai-tree__chev{display:inline-block;transition:transform .12s}
.dodai-tree details[open]>summary .dodai-tree__chev{transform:rotate(90deg)}
.dodai-datatable{display:grid;width:100%}
.dodai-datatable__row{display:grid;grid-template-columns:repeat(var(--cols,4),1fr);width:100%}
.dodai-code{display:block;white-space:pre;overflow:auto;max-width:520px;font-family:var(--dodai-font-mono);font-size:var(--dodai-size-sm);margin:0}
.dodai-empty{display:grid;justify-items:center;gap:var(--dodai-space-xs);padding:var(--dodai-space-lg);text-align:center}
.dodai-swatch{display:grid;gap:4px;width:104px}
.dodai-swatch__chip{height:44px;border:1px solid var(--dodai-border);border-radius:min(var(--dodai-radius),10px)}
.dodai-list--plain{max-width:520px}
.dodai-list--plain .dodai-kit{border-radius:0}
.dodai-grow{flex:1 1 auto;min-width:0}
.dodai-col-text{display:grid}

/* Showcase shell */
.dodai-app{display:grid;grid-template-columns:260px 1fr;height:100vh;overflow:hidden}
.dodai-side{display:flex;flex-direction:column;gap:var(--dodai-space-md);padding:var(--dodai-space-lg);border-right:var(--dodai-border-width) solid var(--dodai-border);min-height:0}
.dodai-side__nav{overflow:auto;min-height:0;flex:1}
.dodai-main{display:flex;flex-direction:column;min-width:0;min-height:0}
.dodai-topbar{display:flex;flex-wrap:wrap;gap:var(--dodai-space-sm) var(--dodai-space-lg);align-items:center;padding:var(--dodai-space-md);border-bottom:var(--dodai-border-width) solid var(--dodai-border)}
.dodai-topbar__field{display:flex;align-items:center;gap:var(--dodai-space-sm)}
.dodai-topbar .dodai-select{width:260px}
.dodai-seg{display:inline-flex;gap:2px}
.dodai-page{overflow:auto;padding:var(--dodai-space-xl);display:grid;gap:var(--dodai-space-lg);align-content:start;flex:1;min-height:0}
.dodai-page h1{margin:0}
.dodai-navitem{width:100%;justify-content:space-between}
.dodai-navsub{padding:4px 8px 4px 36px}

/* See-through fills (glass_style): a fill of alpha a is drawn at (a + (min(c, a) - a) * --ga) * --go
   with c = --gc + (a - --gc) * --gk; frosted ones blur and saturate what is behind them (--gf). */
.dodai-glass{-webkit-backdrop-filter:var(--gf,none);backdrop-filter:var(--gf,none)}
.dodai-glass.dodai-kit{background:rgb(from var(--kb,transparent) r g b/calc((alpha + (min(var(--gc) + (alpha - var(--gc)) * var(--gk),alpha) - alpha) * var(--ga)) * var(--go)))}
.dodai-glass.dodai-kit--press:hover{background:rgb(from var(--kbh,var(--kb,transparent)) r g b/calc((alpha + (min(var(--gc) + (alpha - var(--gc)) * var(--gk),alpha) - alpha) * var(--ga)) * var(--go)))}
.dodai-glass.dodai-btn::after,.dodai-glass.dodai-panel::after{background:rgb(from var(--f-bg,transparent) r g b/calc((alpha + (min(var(--gc) + (alpha - var(--gc)) * var(--gk),alpha) - alpha) * var(--ga)) * var(--go)))}
